import { ReactNode } from 'react';
import { isElement } from 'react-is';

import { DEFAULT_PAGINATION_PAGE_SIZE } from '../DataTable/constants.js';
import { DataTableContextConfig } from '../types/table-config-types.js';

type UsePaginationConfig = Required<DataTableContextConfig>['pagination'];

export function usePaginationSettings(
  config: UsePaginationConfig,
  paginationSlot: ReactNode,
): {
  pageSize?: number;
  pageIndex?: number;
  manualPagination: boolean;
} {
  const hasPaginationSlot = isElement(paginationSlot);
  let slotPageSize: number | undefined = undefined;
  let slotPageIndex: number | undefined = undefined;
  let fallbackPageSize: number | undefined = undefined;
  let manualPagination = false;

  if (hasPaginationSlot) {
    const {
      pageSize,
      defaultPageSize,
      pageIndex,
      defaultPageIndex,
      enableNextPage,
      enablePrevPage,
    } = paginationSlot.props;

    slotPageSize = pageSize ?? defaultPageSize;
    slotPageIndex = pageIndex ?? defaultPageIndex;
    fallbackPageSize = DEFAULT_PAGINATION_PAGE_SIZE;
    manualPagination =
      enableNextPage !== undefined && enablePrevPage !== undefined;
  }

  return {
    pageSize: slotPageSize ?? config.pageSize ?? fallbackPageSize,
    pageIndex: slotPageIndex ?? config.pageIndex,
    manualPagination,
  };
}
